__NUXT_JSONP__("/de/hollywood", (function(a,b){return {data:[{details:{slug:a,pageTitle:"Hollywood Campus | Mentor Language Institute",pageDescription:"Hollywood ist als das Herz der Unterhaltungsindustrie bekannt. Die Oscarverleihung sowie viele Filmpremieren finden im Dolby Theater statt, nur 2 Minuten von unserem Hollywood Campus entfernt.",title:"Hollywood Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fhollywood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FR9QsXd0-Cw8",subtitle:["\u003Cspan class=\"hutoaka\"\u003EHollywood ist als das Herz der Unterhaltungsindustrie bekannt. Die Oscarverleihung sowie viele Filmpremieren finden im Dolby Theater statt, nur 2 Minuten von unserem Hollywood Campus entfernt. Es ist gut möglich, dass du einen berühmten Filmstar in Hollywood sehen wirst, wenn er aus seiner Limousine vor dem Dolby Theater aussteigt!\u003C\u002Fspan\u003E","Unsere Hollywood-Studenten tendieren dazu sich für Unterhaltung zu interessieren wie zum Beispiel Tanz, Musik, Schauspielerei, Film, Yoga und so weiter. Das sehr bekannte Musician's- Institute befindet sich direkt gegenüber von unserem Hollywod Campus.","Des weiteren befinden sich zahlreiche Tanzstudios in der Nähe, wie:"],lists:["Musician Institute","Edge Performing Arts","Millennium Dance Complex","Debbie Raynolds","MovementLifestyle","Los Angeles Film School","NY Film Academy"],other_desc:["Hollywoods kofomtable Lage ist perfekt für internationale Studenten, die auf öffentliche Verkehrsmittel angewiesen sind (die Hollywood & Highland Haltestelle ist nur 2 Gehminuten vom Campus entfernt).","Wenn du gerne in einer kleinen Klasse lernen und der Unterhaltungs- \u002F Film- \u002F Musikindustrie nahe sein möchtest, melde dich am MLI-Hollywood an!"],albums:[{title:"Campus",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-2.jpg"]},{title:b,photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-2.jpg"]}],location:{title:"Standort",link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3303.7636753752786!2d-118.3467233847837!3d34.1011940805926!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bf239f1c4a45%3A0x6953aa45bd461a42!2sMentor%20Language%20Institute%20-%20Hollywood!5e0!3m2!1sen!2sph!4v1576725075448!5m2!1sen!2sph"},video:[{title:"1. Anfahrt zum MLI Hollywood Campus über den Bahnhof Hollywood Highland",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FrP3AV1P3duU"},{title:"2. So gelangen Sie mit dem Auto zum MLI Hollywood Campus",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FJO2iqyI9Dfc"}],accommodation:{title:"Unterkünfte",description:["Wir bieten Gastfamilien und Studentenwohnheime als Unterkünfte an.","＜Studentenwohnheime＞\u003Cbr\u002F\u003E","Unsere Studentenwohnheime befinden sich in bequemer Lage in der Nähe der Schule."],information:[{yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F27o22DzbFp0",desc:["＜Gastfamilien＞ \u003Cbr\u002F\u003E","Gastfamilien sind der beste Weg, um mehr über die amerikanische Kultur zu lernen und deine Möglichkeiten Englisch zu sprechen zu erhöhen.","\u003Ca href=\"\u002Fde\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Mehr Details über die Unterkünfte\u003C\u002Fa\u003E"]}]},courses:{title:b,lists:["ESL Program","TOEFL®","Konversationsprogramm","TOEIC®"]},message:{title:"Nachricht vom Hollywood Campus",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fjulie.jpg",position:"Nachricht vom Campus - direktor",description:["Der MLI Hollywood Campus befindet sich im belebten Zentrum von Hollywood, nur 2 Gehminuten von der U-Bahn Station Hollywood\u002FHighland entfernt. Das Dolby Theatre, das Chinese Theatre und der Walk of Fame befinden sich direkt neben dem Campus und es gibt noch viele weitere Möglichkeiten hier Spass zu haben!"]},dir:"\u002Fhollywood",path:"\u002Fhollywood\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:29.545Z",updatedAt:"2025-05-26T12:06:27.777Z"},lang:a}],fetch:{},mutations:void 0}}("de","Kurse")));